import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let s = conc.Semaphore(1)
    let _ = s.acquire()
    let got = s.tryAcquire()
    if got {
        io.println("bad")
    } else {
        io.println("blocked")
    }
    let _ = s.release()
    let got2 = s.tryAcquire()
    if got2 {
        io.println("free")
    } else {
        io.println("bad2")
    }
    return Ok(())
}
